/**
 * Base Enemy class (`src/core/enemies/Enemy.ts`) providing:
 * - `sensingRange`: Detection radius (Chebyshev distance) for spotting and pursuing the player.
 * - `canOpenDoors`: Whether the enemy can open/close DOOR tiles (false for Chick, Rooster, Dog).
 * - `scoreValue`: Score points awarded when the enemy is defeated.
 * - Default AI (`decideNextAction`):
 *   - Outside `sensingRange` (or when no path exists): Roams randomly (75% step to random adjacent passable tile, 25% wait).
 *   - Inside `sensingRange`: Follows the shortest 8-way A* path toward the player and melee attacks when adjacent.
 */
export class Enemy extends Actor {
  public readonly archetypeId: string;
  public readonly xpReward: number;
  public readonly sensingRange: number;
  public readonly canOpenDoors: boolean;
  public readonly avoidsTraps: boolean;
  public readonly scoreValue: number;
  public readonly dropsMeat: boolean;
  public readonly meatDropChance: number;
  public readonly meatSatietyValue: number;
  public readonly meatWeight: number;
  public readonly trophyDrops: readonly EnemyTrophyDropEntry[];
  public readonly warSkills: readonly EnemyWarSkillEntry[];
  public readonly magicSkills: readonly EnemyMagicSkillEntry[];
  public readonly soulDropId: string | null;
  public readonly soulDropRate: number;
  public aiController?: AIController;
  private _alertedTurns = 0;

  constructor(props: EnemyProps);
  constructor(id: string, position: Point, archetype: EnemyArchetype);
  constructor(
    idOrProps: string | EnemyProps,
    position?: Point,
    archetype?: EnemyArchetype
  ) {
    const resolved: EnemyProps =
      typeof idOrProps === 'string'
        ? {
            id: idOrProps,
            position: position!,
            archetypeId: archetype!.archetypeId,
            name: archetype!.name,
            spriteKey: archetype!.spriteKey,
            isBoss: archetype!.isBoss,
            level: archetype!.level,
            xpReward: archetype!.xpReward,
            movementType: archetype!.movementType,
            sensingRange: archetype!.sensingRange,
            canOpenDoors: archetype!.canOpenDoors,
            avoidsTraps: archetype!.avoidsTraps,
            scoreValue: archetype!.scoreValue,
            dropsMeat: archetype!.dropsMeat,
            meatDropChance: archetype!.meatDropChance,
            meatSatietyValue: archetype!.meatSatietyValue,
            meatWeight: archetype!.meatWeight,
            trophyDrops: archetype!.trophyDrops,
            warSkills: archetype!.warSkills,
            magicSkills: archetype!.magicSkills,
            soulDropId: archetype!.soulDropId,
            soulDropRate: archetype!.soulDropRate,
            attributes: archetype!.attributes,
            stats: archetype!.stats,
            aiController: archetype!.aiController,
          }
        : idOrProps;

    const resolvedLevel = Math.max(1, Math.floor(resolved.level ?? 1));

    super({
      id: resolved.id,
      name: resolved.name,
      position: resolved.position,
      spriteKey: resolved.spriteKey,
      level: resolvedLevel,
      movementType: resolved.movementType ?? 'walking',
      isPlayer: false,
      isBoss: resolved.isBoss ?? false,
      attributes: resolved.attributes,
      stats: resolved.stats,
    });

    this.archetypeId = resolved.archetypeId;
    this.xpReward = Math.max(0, Math.floor(resolved.xpReward ?? resolvedLevel * 10));
    this.sensingRange = Math.max(0, resolved.sensingRange ?? DEFAULT_ENEMY_SENSING_RANGE);
    this.canOpenDoors = resolved.canOpenDoors ?? false;
    this.avoidsTraps = resolved.avoidsTraps ?? false;
    this.scoreValue = Math.max(0, resolved.scoreValue ?? DEFAULT_ENEMY_SCORE_VALUE);
    this.dropsMeat = resolved.dropsMeat ?? true;
    this.meatDropChance = Math.max(
      0,
      Math.min(1, resolved.meatDropChance ?? DEFAULT_ENEMY_MEAT_DROP_CHANCE)
    );
    this.meatSatietyValue = Math.max(1, resolved.meatSatietyValue ?? DEFAULT_ENEMY_MEAT_SATIETY);
    this.meatWeight = Math.max(0, resolved.meatWeight ?? DEFAULT_ENEMY_MEAT_WEIGHT);
    this.trophyDrops = resolved.trophyDrops ? [...resolved.trophyDrops] : [];
    this.warSkills = resolved.warSkills ? [...resolved.warSkills] : [];
    this.magicSkills = resolved.magicSkills ? [...resolved.magicSkills] : [];
    this.soulDropId = resolved.soulDropId ?? null;
    this.soulDropRate = Math.max(
      0,
      Math.min(1, resolved.soulDropRate ?? DEFAULT_SOUL_DROP_RATE)
    );
    this.aiController = resolved.aiController;
  }

  public get alertedTurns(): number {
    return this._alertedTurns;
  }

  /**
   * Alerts this enemy to the player's presence for at least `turns` active turns
   * so it pursues the player even when outside `sensingRange`.
   */
  public alertToPlayer(turns = DEFAULT_ENEMY_ALERTED_TURNS): number {
    const clamped = Math.max(0, Math.floor(turns));
    this._alertedTurns = Math.max(this._alertedTurns, clamped);
    return this._alertedTurns;
  }

  public setAlertedTurns(turns: number): void {
    this._alertedTurns = Math.max(0, Math.floor(turns));
  }

  public decrementAlertedTurn(): number {
    if (this._alertedTurns <= 0) {
      return 0;
    }
    this._alertedTurns = Math.max(0, this._alertedTurns - 1);
    return this._alertedTurns;
  }

  public override addSleepTurns(turns: number): number {
    const updated = super.addSleepTurns(turns);
    if (this.isAsleep()) {
      this._alertedTurns = 0;
    }
    return updated;
  }

  public override setSleepTurns(turns: number): void {
    super.setSleepTurns(turns);
    if (this.isAsleep()) {
      this._alertedTurns = 0;
    }
  }

  /**
   * Selects an adjacent offensive action against `target`:
   * - If `this.warSkills` contains usable adjacent skills (`targeting === 'adjacent'`, `sp >= skill.spCost`),
   *   rolls once across their configured chances (e.g. `Dog` 30% `Bite`, `Bee` 30% `Pierce`), falling back to `MeleeAttackAction` (`70%`).
   * - If `sp < 10`, returns `WaitAction` to rest and regenerate stamina.
   */
  public decideAdjacentAttackAction(target: Actor, world: GameWorld): Action {
    if (this.warSkills.length > 0) {
      const usable = this.warSkills.filter((entry) => {
        const def = getWarSkillById(entry.skillId);
        return Boolean(
          def && def.targeting === 'adjacent' && entry.chance > 0 && this.stats.sp >= def.spCost
        );
      });
      if (usable.length > 0) {
        const configuredSkillWeight =
          this.warSkills.reduce((acc, e) => acc + Math.max(0, e.chance), 0) +
          this.magicSkills.reduce((acc, e) => acc + Math.max(0, e.chance), 0);
        const fallbackWeight = Math.max(0, 1 - configuredSkillWeight);
        const usableSum = usable.reduce((acc, e) => acc + e.chance, 0);
        const totalActiveWeight = usableSum + fallbackWeight;
        if (totalActiveWeight > 0) {
          const roll = world.nextRandom() * totalActiveWeight;
          let cumulative = 0;
          for (const entry of usable) {
            cumulative = Number((cumulative + entry.chance).toFixed(9));
            if (roll < cumulative) {
              return new WarSkillAction(target, entry.skillId);
            }
          }
        }
      }
    }
    if (this.stats.sp >= MELEE_SP_COST) {
      return new MeleeAttackAction(target);
    }
    return new WaitAction();
  }

  /**
   * Evaluates spellcasting actions (`this.magicSkills`, e.g., `Cat`'s 20% `Clever` / 20% `Fireball` / 60% Melee-or-Advance)
   * proportionally across currently valid options when perceiving `@`.
   */
  public tryDecideMagicSkillAction(world: GameWorld, chebyshevDist: number): Action | null {
    if (this.magicSkills.length === 0) {
      return null;
    }
    let configuredMagicWeight = 0;
    const eligible: Array<{ entry: EnemyMagicSkillEntry; targetPos: Point }> = [];

    for (const entry of this.magicSkills) {
      if (entry.chance <= 0) {
        continue;
      }
      configuredMagicWeight += entry.chance;
      const def = getMagicSkillById(entry.skillId);
      if (!def || this.stats.mp < def.mpCost) {
        continue;
      }
      if (def.targeting === 'self') {
        if (
          (def.selfBuff?.effectId === 'clever' && this.hasClever()) ||
          (def.selfBuff?.effectId === 'shield' && this.hasShield()) ||
          (def.selfBuff?.effectId === 'scud' && this.hasScud())
        ) {
          continue;
        }
        eligible.push({ entry, targetPos: { ...this.position } });
      } else if (def.targeting === 'ranged_tile') {
        const maxRange = def.range ?? 8;
        const canReachMagic =
          chebyshevDist >= 1 &&
          chebyshevDist <= maxRange &&
          (def.piercesLine
            ? world.hasClearLineMagicPath(this.position, world.player.position, maxRange)
            : world.hasClearRangedMagicLineOfFire(this.position, world.player.position, maxRange));
        if (canReachMagic) {
          eligible.push({ entry, targetPos: { ...world.player.position } });
        }
      } else if (def.targeting === 'adjacent') {
        if (isAdjacent(this.position, world.player.position)) {
          eligible.push({ entry, targetPos: { ...world.player.position } });
        }
      }
    }

    if (eligible.length === 0) {
      return null;
    }

    const fallbackWeight = Math.max(0, 1 - configuredMagicWeight);
    const eligibleSum = eligible.reduce((acc, item) => acc + item.entry.chance, 0);
    const totalActiveWeight = eligibleSum + fallbackWeight;
    if (totalActiveWeight <= 0) {
      return null;
    }

    const roll = world.nextRandom() * totalActiveWeight;
    let cumulative = 0;
    for (const item of eligible) {
      cumulative = Number((cumulative + item.entry.chance).toFixed(9));
      if (roll < cumulative) {
        return new MagicSkillAction(item.targetPos, item.entry.skillId);
      }
    }
    return null;
  }

  /**
   * Unified proportional combat skill selector across both `this.warSkills` and `this.magicSkills`
   * when perceiving `@`:
   * - Weighs all currently eligible War & Magic skills against `baseFallbackWeight = max(0, 1 - sum(configured))`.
   * - Out-of-range `'adjacent'` skills fold their configured weight into `effectiveFallbackWeight` (`A*` Advance)
   *   so ranged/self buffs keep their exact configured cast probability while closing distance (e.g., `Wolf` rolls
   *   `40% Scud / 60% Advance` at range, `40% Bite / 40% Scud / 20% Melee` when adjacent unbuffed, and
   *   `2/3 Bite / 1/3 Melee` when adjacent while `Scud` is already active).
   * - Consumes zero RNG rolls when no skill is eligible.
   */
  public tryDecideCombatSkillAction(world: GameWorld, chebyshevDist: number): Action | null {
    if (this.warSkills.length === 0 && this.magicSkills.length === 0) {
      return null;
    }

    const adjacentToPlayer = isAdjacent(this.position, world.player.position);
    let totalConfiguredWeight = 0;
    let outOfRangeAdjacentWeight = 0;
    const eligible: Array<{ weight: number; createAction: () => Action }> = [];

    for (const entry of this.warSkills) {
      if (entry.chance <= 0) {
        continue;
      }
      totalConfiguredWeight += entry.chance;
      const def = getWarSkillById(entry.skillId);
      if (!def) {
        continue;
      }
      if (def.targeting === 'adjacent') {
        if (!adjacentToPlayer) {
          outOfRangeAdjacentWeight += entry.chance;
          continue;
        }
        if (this.stats.sp >= def.spCost) {
          eligible.push({
            weight: entry.chance,
            createAction: () => new WarSkillAction(world.player, entry.skillId),
          });
        }
      } else if (def.targeting === 'self') {
        if (this.stats.sp < def.spCost) {
          continue;
        }
        if (
          (def.selfBuff?.effectId === 'invisible' && this.isInvisible()) ||
          (def.selfBuff?.effectId === 'roar' && this.hasRoar()) ||
          (def.selfBuff?.effectId === 'tough' && this.hasTough())
        ) {
          continue;
        }
        eligible.push({
          weight: entry.chance,
          createAction: () => new WarSkillAction(this, entry.skillId),
        });
      } else if (def.targeting === 'ranged_tile') {
        const maxRange = def.range ?? 5;
        const canReachRangedWar =
          chebyshevDist >= 1 &&
          chebyshevDist <= maxRange &&
          (def.isShadowBlink
            ? world.canActorShadowBlinkToTarget(this, world.player, maxRange)
            : world.hasClearChargeLine(this, world.player.position, maxRange));
        if (!canReachRangedWar) {
          outOfRangeAdjacentWeight += entry.chance;
          continue;
        }
        if (this.stats.sp >= def.spCost) {
          eligible.push({
            weight: entry.chance,
            createAction: () => new WarSkillAction(world.player, entry.skillId),
          });
        }
      }
    }

    for (const entry of this.magicSkills) {
      if (entry.chance <= 0) {
        continue;
      }
      totalConfiguredWeight += entry.chance;
      const def = getMagicSkillById(entry.skillId);
      if (!def) {
        continue;
      }
      if (def.targeting === 'adjacent') {
        if (!adjacentToPlayer) {
          outOfRangeAdjacentWeight += entry.chance;
          continue;
        }
        if (this.stats.mp >= def.mpCost) {
          const targetPos = { ...world.player.position };
          eligible.push({
            weight: entry.chance,
            createAction: () => new MagicSkillAction(targetPos, entry.skillId),
          });
        }
      } else if (def.targeting === 'self') {
        if (this.stats.mp < def.mpCost) {
          continue;
        }
        if (
          (def.selfBuff?.effectId === 'clever' && this.hasClever()) ||
          (def.selfBuff?.effectId === 'shield' && this.hasShield()) ||
          (def.selfBuff?.effectId === 'scud' && this.hasScud())
        ) {
          continue;
        }
        const selfPos = { ...this.position };
        eligible.push({
          weight: entry.chance,
          createAction: () => new MagicSkillAction(selfPos, entry.skillId),
        });
      } else if (def.targeting === 'ranged_tile') {
        const maxRange = def.range ?? 8;
        const canReachMagic =
          chebyshevDist >= 1 &&
          chebyshevDist <= maxRange &&
          (def.piercesLine
            ? world.hasClearLineMagicPath(this.position, world.player.position, maxRange)
            : world.hasClearRangedMagicLineOfFire(this.position, world.player.position, maxRange));
        if (!canReachMagic) {
          outOfRangeAdjacentWeight += entry.chance;
          continue;
        }
        if (this.stats.mp >= def.mpCost) {
          const targetPos = { ...world.player.position };
          eligible.push({
            weight: entry.chance,
            createAction: () => new MagicSkillAction(targetPos, entry.skillId),
          });
        }
      }
    }

    if (eligible.length === 0) {
      return null;
    }

    const baseFallbackWeight = Math.max(0, 1 - totalConfiguredWeight);
    const effectiveFallbackWeight = baseFallbackWeight + outOfRangeAdjacentWeight;
    const eligibleSum = eligible.reduce((acc, item) => acc + item.weight, 0);
    const totalActiveWeight = eligibleSum + effectiveFallbackWeight;
    if (totalActiveWeight <= 0) {
      return null;
    }

    const roll = world.nextRandom() * totalActiveWeight;
    let cumulative = 0;
    for (const item of eligible) {
      cumulative = Number((cumulative + item.weight).toFixed(9));
      if (roll < cumulative) {
        return item.createAction();
      }
    }
    return null;
  }

  /**
   * Evaluates self-targeted tactical War Skills (such as `Rat`'s `Hide` -> `Invisible`) when pursuing or engaging `@`.
   * Skips buffs that are already active on `this` (`!this.isInvisible()`) so the enemy commits 100% to attacking once stealthed.
   */
  public tryDecideSelfWarSkillAction(world: GameWorld): Action | null {
    if (this.warSkills.length === 0) {
      return null;
    }
    const usableSelf = this.warSkills.filter((entry) => {
      const def = getWarSkillById(entry.skillId);
      if (!def || def.targeting !== 'self' || entry.chance <= 0 || this.stats.sp < def.spCost) {
        return false;
      }
      if (
        (def.selfBuff?.effectId === 'invisible' && this.isInvisible()) ||
        (def.selfBuff?.effectId === 'roar' && this.hasRoar()) ||
        (def.selfBuff?.effectId === 'tough' && this.hasTough())
      ) {
        return false;
      }
      return true;
    });
    if (usableSelf.length === 0) {
      return null;
    }
    const roll = world.nextRandom();
    let cumulative = 0;
    for (const entry of usableSelf) {
      cumulative = Number((cumulative + entry.chance).toFixed(9));
      if (roll < cumulative) {
        return new WarSkillAction(this, entry.skillId);
      }
    }
    return null;
  }

  /**
   * Evaluates ranged movement/impact War Skills (such as `Boar`'s `Charge` at `1..5` tiles) when perceiving `@`.
   * Rolls against `entry.chance` (e.g., `30%` `Charge` vs. `70%` Melee-or-Advance) iff `sp >= spCost` and
   * `world.hasClearChargeLine(this, world.player.position, maxRange)` is true.
   */
  public tryDecideRangedWarSkillAction(world: GameWorld, chebyshevDist: number): Action | null {
    if (this.warSkills.length === 0) {
      return null;
    }
    const usableRanged = this.warSkills.filter((entry) => {
      const def = getWarSkillById(entry.skillId);
      if (!def || def.targeting !== 'ranged_tile' || entry.chance <= 0 || this.stats.sp < def.spCost) {
        return false;
      }
      const maxRange = def.range ?? 5;
      return (
        chebyshevDist >= 1 &&
        chebyshevDist <= maxRange &&
        (def.isShadowBlink
          ? world.canActorShadowBlinkToTarget(this, world.player, maxRange)
          : world.hasClearChargeLine(this, world.player.position, maxRange))
      );
    });
    if (usableRanged.length === 0) {
      return null;
    }
    const roll = world.nextRandom();
    let cumulative = 0;
    for (const entry of usableRanged) {
      cumulative = Number((cumulative + entry.chance).toFixed(9));
      if (roll < cumulative) {
        return new WarSkillAction(world.player, entry.skillId);
      }
    }
    return null;
  }

  /**
   * Determines the enemy's next action on the timeline:
   * 1. Delegates to `this.aiController` if a custom AIController is attached.
   * 2. If the player is alive and within `this.sensingRange`:
   *    - Attacks immediately with `decideAdjacentAttackAction` if adjacent to the player.
   *    - Otherwise steps along the shortest 8-way path toward `player.position` (respecting `canOpenDoors`).
   * 3. Otherwise (outside `sensingRange` or blocked by closed doors/walls):
   *    - Roams by stepping onto a random valid adjacent passable tile (75% chance) or waiting 1 turn (25% chance).
   */
  public decideNextAction(world: GameWorld): Action {
    if (this.aiController) {
      return this.aiController.decideNextAction(this, world);
    }

    // Terrified / Fleeing AI (`scaredTurns > 0`, e.g. from `Scroll of Scare Monster`):
    // Skips all offensive attacks and skills; moves away from `@` if perceiving `@`, or cowers in place (`WaitAction`) if cornered.
    if (this.isScared()) {
      if (!world.player.isAlive() || !world.canActorPerceiveTarget(this, world.player)) {
        return this.decideRoamAction(world);
      }
      return this.decideFleeFromPlayerAction(world);
    }

    // Blind / Unseen Target AI: cannot spot the player via vision (`sensingRange` ignored) whenever
    // `world.canActorPerceiveTarget(this, world.player)` is false (Blind, unseen Invisible player,
    // submerged player while enemy is outside/above water, or above-water player while non-Swimming enemy is submerged).
    // If previously alerted (`alertedTurns > 0`), mixes 50% random adjacent wild swings with 50% random roaming;
    // otherwise (`alertedTurns === 0`), executes pure random roaming.
    if (!world.canActorPerceiveTarget(this, world.player)) {
      if (this._alertedTurns > 0 && world.player.isAlive()) {
        if (this.stats.sp >= MELEE_SP_COST && world.nextRandom() < 0.5) {
          const dirIdx = Math.min(
            ALL_DIRECTIONS.length - 1,
            Math.max(0, Math.floor(world.nextRandom() * ALL_DIRECTIONS.length))
          );
          const chosenDir = ALL_DIRECTIONS[dirIdx];
          const chosenSpot: Point = {
            x: this.position.x + chosenDir.dx,
            y: this.position.y + chosenDir.dy,
          };
          if (pointsEqual(chosenSpot, world.player.position)) {
            return this.decideAdjacentAttackAction(world.player, world);
          }
          return new EnemyBlindSwingAction();
        }
      }
      return this.decideRoamAction(world);
    }

    if (world.player.isAlive()) {
      const baseRange =
        world.isActorSubmergedInWater(this) && this.movementType !== 'swimming'
          ? Math.max(1, Math.floor(this.sensingRange / 2))
          : this.sensingRange;
      const effectiveSensingRange = this.isTrappedInPit()
        ? Math.min(1, baseRange)
        : baseRange;
      const chebyshevDist = Math.max(
        Math.abs(this.position.x - world.player.position.x),
        Math.abs(this.position.y - world.player.position.y)
      );

      if (chebyshevDist <= effectiveSensingRange) {
        // Remember having sensed the player (`+1` offsets the end-of-turn decrement so 15 full turns remain)
        this.alertToPlayer(DEFAULT_ENEMY_ALERTED_TURNS + 1);
      }

      if (chebyshevDist <= effectiveSensingRange || (!this.isTrappedInPit() && this._alertedTurns > 0)) {
        const combatSkillAction = this.tryDecideCombatSkillAction(world, chebyshevDist);
        if (combatSkillAction) {
          return combatSkillAction;
        }
        if (isAdjacent(this.position, world.player.position)) {
          return this.stats.sp >= MELEE_SP_COST
            ? new MeleeAttackAction(world.player)
            : new WaitAction();
        }

        const path = findShortestPathForEnemy(
          world,
          this.position,
          world.player.position,
          this.canOpenDoors,
          this.avoidsTraps,
          this.movementType
        );
        if (path && path.length > 0) {
          return MoveAction.fromTargetPoint(this.position, path[0]);
        }
      }
    }

    return this.decideRoamAction(world);
  }

  /**
   * Default roaming behavior when the player is outside `sensingRange` (or unreachable):
   * - Collects all unoccupied adjacent tiles that this enemy can step onto.
   * - Waits 1 turn if boxed in or on a 25% idle roll; otherwise moves to a random valid adjacent tile.
   */
  protected decideRoamAction(world: GameWorld): Action {
    const candidates = world.map.getAdjacentPoints(this.position, true).filter((pt) => {
      const tile = world.map.getTile(pt.x, pt.y);
      if (!tile) {
        return false;
      }
      const canTraverseTile =
        this.canTraverseTile(tile) ||
        (this.movementType !== 'swimming' && this.canOpenDoors && tile.isClosedDoor());
      if (!canTraverseTile) {
        return false;
      }
      if (this.avoidsTraps) {
        const trap = world.getTrapAt(pt);
        if (trap && trapAffectsMovementType(trap.trapTypeId, this.movementType)) {
          return false;
        }
      }
      return world.getBlockingActorAt(pt) === null;
    });

    if (candidates.length === 0 || world.nextRandom() < 0.25) {
      return new WaitAction();
    }

    const chosenIndex = Math.floor(world.nextRandom() * candidates.length);
    const chosenPoint = candidates[Math.min(candidates.length - 1, Math.max(0, chosenIndex))];
    return MoveAction.fromTargetPoint(this.position, chosenPoint);
  }

  /**
   * Fleeing behavior while `this.isScared()` (`scaredTurns > 0`):
   * - Evaluates unoccupied passable adjacent tiles (respecting `movementType`, `canOpenDoors`, and `avoidsTraps`).
   * - Picks a retreat step maximizing Chebyshev distance (with squared Euclidean tie-breaker) away from `player.position`
   *   without ever stepping closer.
   * - If cornered with no valid tile that increases distance, cowers in place (`WaitAction`) without attacking.
   */
  protected decideFleeFromPlayerAction(world: GameWorld): Action {
    const px = world.player.position.x;
    const py = world.player.position.y;
    const curDx = this.position.x - px;
    const curDy = this.position.y - py;
    const curCheb = Math.max(Math.abs(curDx), Math.abs(curDy));
    const curDistSq = curDx * curDx + curDy * curDy;

    const retreatCandidates: Array<{ pt: Point; cheb: number; distSq: number }> = [];
    for (const pt of world.map.getAdjacentPoints(this.position, true)) {
      const tile = world.map.getTile(pt.x, pt.y);
      if (!tile) {
        continue;
      }
      const canTraverse =
        this.canTraverseTile(tile) ||
        (this.movementType !== 'swimming' && this.canOpenDoors && tile.isClosedDoor());
      if (!canTraverse) {
        continue;
      }
      if (this.avoidsTraps) {
        const trap = world.getTrapAt(pt);
        if (trap && trapAffectsMovementType(trap.trapTypeId, this.movementType)) {
          continue;
        }
      }
      if (world.getBlockingActorAt(pt) !== null) {
        continue;
      }
      const dx = pt.x - px;
      const dy = pt.y - py;
      const cheb = Math.max(Math.abs(dx), Math.abs(dy));
      const distSq = dx * dx + dy * dy;
      if (cheb > curCheb || (cheb === curCheb && distSq > curDistSq)) {
        retreatCandidates.push({ pt, cheb, distSq });
      }
    }

    if (retreatCandidates.length === 0) {
      return new WaitAction();
    }

    retreatCandidates.sort((a, b) => {
      if (b.cheb !== a.cheb) return b.cheb - a.cheb;
      return b.distSq - a.distSq;
    });
    const bestCheb = retreatCandidates[0].cheb;
    const bestDistSq = retreatCandidates[0].distSq;
    const topTies = retreatCandidates.filter(
      (c) => c.cheb === bestCheb && c.distSq === bestDistSq
    );
    const chosen =
      topTies.length === 1
        ? topTies[0]
        : topTies[Math.min(topTies.length - 1, Math.floor(world.nextRandom() * topTies.length))];
    return MoveAction.fromTargetPoint(this.position, chosen.pt);
  }

  /**
   * Subclasses override this to persist enemy-specific custom state.
   */
  public serializeCustomData(): Record<string, unknown> {
    return {};
  }

  public toSaveData(): SerializedEnemy {
    const custom = this.serializeCustomData();
    const hasCustom = Object.keys(custom).length > 0;
    return {
      archetypeId: this.archetypeId,
      ...(this.isBoss ? { isBoss: true } : {}),
      xpReward: this.xpReward,
      sensingRange: this.sensingRange,
      ...(this._alertedTurns > 0 ? { alertedTurns: this._alertedTurns } : {}),
      canOpenDoors: this.canOpenDoors,
      ...(this.avoidsTraps ? { avoidsTraps: true } : {}),
      scoreValue: this.scoreValue,
      dropsMeat: this.dropsMeat,
      meatDropChance: this.meatDropChance,
      meatSatietyValue: this.meatSatietyValue,
      meatWeight: this.meatWeight,
      ...(this.soulDropId ? { soulDropId: this.soulDropId, soulDropRate: this.soulDropRate } : {}),
      actorState: this.toActorSaveState(),
      ...(hasCustom ? { customData: custom } : {}),
    };
  }
}
