import { FoodItem, FoodItemOptions } from './FoodItem';

export type CheeseOptions = FoodItemOptions;

/**
 * Cheese (`起司`): aged golden non-perishable dungeon food dropped by Rats (`10%`).
 * Restores +100 Satiety over 5–10 turns via the 'e' Food Tab, stacks cleanly, and never rots.
 */
export class Cheese extends FoodItem {
  constructor(options: CheeseOptions) {
    const baseSatietyValue = options.baseSatietyValue ?? 100;
    super({
      id: options.id ?? `cheese-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Cheese',
      itemTypeId: 'cheese',
      spriteKey: 'item_cheese',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.8,
      stackable: true,
      baseSatietyValue,
      eatMinTurns: options.eatMinTurns,
      eatMaxTurns: options.eatMaxTurns,
      description:
        options.description ??
        `Aged golden dungeon cheese that never spoils and restores ${baseSatietyValue} Satiety when eaten.`,
    });
  }

  public override cloneWithAmount(newAmount: number, newId?: string): Cheese {
    return new Cheese({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      baseSatietyValue: this.baseSatietyValue,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    });
  }
}
