import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const DEFAULT_SLEEP_MIN_TURNS = 10;
export const DEFAULT_SLEEP_MAX_TURNS = 20;

export interface SleepPotionOptions extends PotionItemOptions {
  readonly minTurns?: number;
  readonly maxTurns?: number;
}

/**
 * Potion of Sleep (`睡眠藥水`): inflicts 10–20 turns of additive Sleep (`Asleep`) on its target
 * when quaffed (+10 Satiety) or thrown (wakes immediately on taking HP damage).
 */
export class SleepPotion extends PotionItem {
  public readonly minTurns: number;
  public readonly maxTurns: number;

  constructor(options: SleepPotionOptions) {
    const minTurns = Math.max(1, Math.round(options.minTurns ?? DEFAULT_SLEEP_MIN_TURNS));
    const maxTurns = Math.max(
      minTurns,
      Math.round(options.maxTurns ?? DEFAULT_SLEEP_MAX_TURNS)
    );
    super({
      id: options.id ?? `sleep-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Sleep',
      itemTypeId: 'sleep_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A soporific draught that puts its target into a deep sleep for ${minTurns}–${maxTurns} turns when quaffed or thrown (wakes on damage).`,
    });
    this.minTurns = minTurns;
    this.maxTurns = maxTurns;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW'
      ? `睡眠 ${this.minTurns}–${this.maxTurns}回合`
      : `Sleep ${this.minTurns}–${this.maxTurns}t`;
  }

  public applyToTarget(target: Actor, rng?: SeededRNG): number {
    if (!target.isAlive() || target.isAsleep()) {
      return 0;
    }
    const rolledTurns = rng
      ? rng.nextInt(this.minTurns, this.maxTurns)
      : Math.floor(Math.random() * (this.maxTurns - this.minTurns + 1)) + this.minTurns;
    return target.addSleepTurns(rolledTurns);
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const added = this.applyToTarget(target, rng);
    return {
      kind: 'sleep',
      observableEffect: added > 0,
      sleepTurnsAdded: added,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): SleepPotion {
    const cloned = new SleepPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
    };
  }
}

registerPotionType('sleep_potion');
