import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type EnchantArmorScrollOptions = ScrollItemOptions;

/**
 * Scroll of Enchant Armor (`附魔防具卷軸`) — lets the player select 1 currently equipped
 * armor piece (`Head`, `Body`, `Arms`, `Shield`, `Feet`) to increase its `DEF` by +1 (`+1..+5`;
 * attempting to enchant a `+5` armor evaporates and destroys it).
 */
export class EnchantArmorScroll extends ScrollItem {
  public readonly scrollKind = 'enchant_armor' as const;

  constructor(options: EnchantArmorScrollOptions) {
    super({
      id: options.id ?? `enchant-armor-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Enchant Armor',
      itemTypeId: 'enchant_armor_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'Reinforces a chosen piece of equipped armor with +1 DEF (up to +5; enchanting beyond +5 evaporates it!).',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '選擇裝備防具防禦 +1' : 'Armor DEF +1';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): EnchantArmorScroll {
    return new EnchantArmorScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('enchant_armor_scroll');
