import { ConcreteItemOptions, Item, ItemProps } from './Item';

export type ScrollKind =
  | 'identify'
  | 'teleport'
  | 'create_monster'
  | 'scare_monster'
  | 'enchant_weapon'
  | 'enchant_armor'
  | 'destroy_armor';

export interface ScrollItemProps extends Omit<ItemProps, 'itemType' | 'spriteKey'> {
  readonly spriteKey?: string;
}

export type ScrollItemOptions = ConcreteItemOptions;

/**
 * Base class for all readable scrolls ('r' Scroll Tab) sharing the `item_scroll` icon
 * and participating in the per-run randomized arcane rune label & Identify system.
 */
export abstract class ScrollItem extends Item {
  public readonly isScroll = true as const;
  public abstract readonly scrollKind: ScrollKind;

  constructor(props: ScrollItemProps) {
    super({
      ...props,
      itemType: 'consumable',
      spriteKey: props.spriteKey ?? 'item_scroll',
      weight: props.weight ?? 0.2,
      stackable: props.stackable ?? true,
    });
  }

  /**
   * Short effect badge shown in the Upper Item Description Tab once identified.
   */
  public abstract getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string;
}

export function isScrollItem(item: Item): item is ScrollItem {
  return item instanceof ScrollItem;
}
