import { buildEnemyRawMaterialDrops } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface EarthDragonOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Earth Dragon (`岩龍`):
 * - Towering `Lv. 8` obsidian-amber terrestrial crag dragon (`Walking`, `sensingRange = 8`, `canOpenDoors = false`).
 * - 5-Way Hybrid Combat AI:
 *   - `20%` `Shield` (`鐵壁`, `10 MP`, `+10` full turns of `+50% DEF` min `+5` when `!hasShield()`),
 *   - `20%` `Bash` (`猛擊`, `10 SP`, adjacent, `30%` non-stacking `Faint` `2–4t`),
 *   - `20%` `Rock Missile` (`飛岩`, `10 MP`, `1..8` tiles),
 *   - `20%` `Rock Pierce` (`岩突`, `20 MP`, `1..5` tile line-piercing stone spikes),
 *   - `20%` `Melee` / `A*` Advance.
 * - Drops `Meat of Earth Dragon` (`岩龍肉`, `10%`, `+350` Satiety, `4.5 wt`) and `Rock Pierce` (`岩突`) Soul (`5%`), with no crafting trophy drops.
 */
export class EarthDragon extends Enemy {
  constructor(options: EarthDragonOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_earth_dragon',
      name: 'Earth Dragon',
      position: options.position,
      spriteKey: 'enemy_earth_dragon',
      level: 8,
      xpReward: 325,
      movementType: 'walking',
      sensingRange: 8,
      canOpenDoors: false,
      scoreValue: 750,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 350,
      meatWeight: 4.5,
      soulDropId: 'rock_pierce',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [{ skillId: 'bash', chance: 0.2 }],
      magicSkills: [
        { skillId: 'shield', chance: 0.2 },
        { skillId: 'rock_missile', chance: 0.2 },
        { skillId: 'rock_pierce', chance: 0.2 },
      ],
      trophyDrops: buildEnemyRawMaterialDrops('enemy_earth_dragon'),
      attributes: {
        str: 22,
        con: 24,
        int: 16,
        wis: 14,
        agi: 11,
        luk: 10,
      },
    });
  }
}
