import { FoodItem, FoodItemOptions } from './FoodItem';

export type HoneyOptions = FoodItemOptions;

/**
 * Honey (`蜂蜜`): golden non-perishable dungeon food dropped by Bees (`10%`).
 * Restores +100 Satiety over 5–10 turns via the 'e' Food Tab, stacks cleanly, and never rots.
 */
export class Honey extends FoodItem {
  constructor(options: HoneyOptions) {
    const baseSatietyValue = options.baseSatietyValue ?? 100;
    super({
      id: options.id ?? `honey-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Honey',
      itemTypeId: 'honey',
      spriteKey: 'item_honey',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.8,
      stackable: true,
      baseSatietyValue,
      eatMinTurns: options.eatMinTurns,
      eatMaxTurns: options.eatMaxTurns,
      description:
        options.description ??
        `Pure golden dungeon honey that never spoils and restores ${baseSatietyValue} Satiety when eaten.`,
    });
  }

  public override cloneWithAmount(newAmount: number, newId?: string): Honey {
    return new Honey({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      baseSatietyValue: this.baseSatietyValue,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    });
  }
}
