const PLAYER_ACTOR_TOKEN = '@player';
const BLIND_UNSEEN_ACTOR_TOKEN = '@something';

function resolvePlayerAwareTemplate(
  lang: LanguageCode,
  key: LogMessageKey,
  defaultTemplate: string,
  params?: Readonly<Record<string, string | number>>
): string {
  if (!params) {
    return defaultTemplate;
  }
  const actorIsPlayer = params.actor === PLAYER_ACTOR_TOKEN;
  const attackerIsPlayer = params.attacker === PLAYER_ACTOR_TOKEN;
  const defenderIsPlayer = params.defender === PLAYER_ACTOR_TOKEN;
  const blockerIsPlayer = params.blocker === PLAYER_ACTOR_TOKEN;

  if (lang === 'en') {
    if (actorIsPlayer) {
      switch (key) {
        case 'enteredDungeon':
          return 'You entered the dungeon ({generator}, seed: {seed}).';
        case 'waits':
          return 'You wait.';
        case 'seesItemsHere':
          return 'You see {items} here.';
        case 'blindFeelsItemsHere':
          return 'You feel {items} here.';
        case 'tooHeavyToCarry':
          return 'You cannot carry {item} — too heavy!';
        case 'pickedUpItems':
          return 'You picked up {items}.';
        case 'droppedItems':
          return 'You dropped {items}.';
        case 'opensDoor':
          return 'You open the door.';
        case 'closesDoor':
          return 'You close the door.';
        case 'attackEmptyAir':
          return 'You swing at empty air.';
        case 'attributeIncreased':
          return 'You gained +1 {attr}! ({oldVal} → {newVal})';
        default:
          break;
      }
    }
    if (blockerIsPlayer && key === 'blockingTheWay') {
      return 'You are blocking the way.';
    }
    if (key === 'attackHit') {
      if (attackerIsPlayer) return 'You attack {defender} for {damage} damage.';
      if (defenderIsPlayer) return '{attacker} attacks you for {damage} damage.';
    }
    if (key === 'attackCrit') {
      if (attackerIsPlayer) return 'Critical hit! You strike {defender} for {damage} damage!';
      if (defenderIsPlayer) return 'Critical hit! {attacker} strikes you for {damage} damage!';
    }
    if (key === 'attackMissed') {
      if (attackerIsPlayer) return 'You attack {defender}, but miss.';
      if (defenderIsPlayer) return '{attacker} attacks you, but misses.';
    }
    if (key === 'actorDefeated' && defenderIsPlayer) {
      return 'You are defeated!';
    }
    if (defenderIsPlayer) {
      switch (key) {
        case 'throwItemHitNoDamage':
          return 'You throw {item} at yourself!';
        case 'throwItemHitDamage':
          return 'You throw {item} and hit yourself for {damage} damage!';
        case 'throwPotionRestore':
          return 'You throw {item} at yourself and recover {amount} {stat}!';
        case 'throwPotionIdentifyRestore':
          return 'You throw {item} at yourself and recover {amount} {stat}! It was {trueItem}!';
        case 'throwPotionParalyze':
          return 'You throw {item} at yourself and become paralyzed for {turns} turns!';
        case 'throwPotionIdentifyParalyze':
          return 'You throw {item} at yourself and become paralyzed for {turns} turns! It was {trueItem}!';
        case 'throwPotionSleep':
          return 'You throw {item} at yourself and fall asleep for {turns} turns!';
        case 'throwPotionIdentifySleep':
          return 'You throw {item} at yourself and fall asleep for {turns} turns! It was {trueItem}!';
        case 'throwPotionBlind':
          return 'You throw {item} at yourself — darkness clouds your vision for {turns} turns!';
        case 'throwPotionIdentifyBlind':
          return 'You throw {item} at yourself — your vision goes dark for {turns} turns! It was {trueItem}!';
        case 'throwPotionSpeed':
          return 'You throw {item} at yourself and move twice as fast for {turns} turns!';
        case 'throwPotionIdentifySpeed':
          return 'You throw {item} at yourself and move twice as fast for {turns} turns! It was {trueItem}!';
        case 'throwPotionInvisible':
          return 'You throw {item} at yourself and fade from sight for {turns} turns!';
        case 'throwPotionIdentifyInvisible':
          return 'You throw {item} at yourself and fade from sight for {turns} turns! It was {trueItem}!';
        case 'throwPotionSeeInvisible':
          return 'You throw {item} at yourself and your eyes tingle with keen sight for {turns} turns!';
        case 'throwPotionIdentifySeeInvisible':
          return 'You throw {item} at yourself and your eyes tingle with keen sight for {turns} turns! It was {trueItem}!';
        case 'throwPotionGrowth':
          return 'You throw {item} at yourself and feel stronger! Your {attr} increased! ({oldVal} → {newVal})';
        case 'throwPotionIdentifyGrowth':
          return 'You throw {item} at yourself and feel stronger! Your {attr} increased! ({oldVal} → {newVal}) It was {trueItem}!';
        case 'throwPotionCureBleeding':
          return 'You throw {item} at yourself and your bleeding stops!';
        case 'throwPotionIdentifyCureBleeding':
          return 'You throw {item} at yourself and your bleeding stops! It was {trueItem}!';
        case 'inflictedBleeding':
          return 'You start bleeding for {turns} turns!';
        case 'inflictedArmorBreak':
          return 'Your armor is shattered for {turns} turns!';
        case 'inflictedFaint':
          return 'You are knocked faint for {turns} turns!';
        case 'inflictedBlind':
          return 'Shadowy mist blinds you for {turns} turns!';
        case 'enemyMagicSkillHit':
          return '{attacker} casts {skill} at you for {damage} damage!';
        case 'chargeKnockback':
          return 'You are knocked back!';
        case 'throwPotionNoEffect':
          return 'You throw {item} at yourself, and the vial shatters with no noticeable effect.';
        default:
          break;
      }
    }
  } else if (lang === 'zh-TW') {
    if (actorIsPlayer) {
      switch (key) {
        case 'enteredDungeon':
          return '你進入了地城（{generator}，種子碼：{seed}）。';
        case 'waits':
          return '你原地等待。';
        case 'seesItemsHere':
          return '你在此處發現了 {items}。';
        case 'blindFeelsItemsHere':
          return '你在腳下摸到了 {items}。';
        case 'tooHeavyToCarry':
          return '你無法拿起 {item}——太重了！';
        case 'pickedUpItems':
          return '你拾取了 {items}。';
        case 'droppedItems':
          return '你丟棄了 {items}。';
        case 'opensDoor':
          return '你打開了門。';
        case 'closesDoor':
          return '你關上了門。';
        case 'attackEmptyAir':
          return '你朝該方向揮空了。';
        case 'attributeIncreased':
          return '你的 {attr} 提升了！（{oldVal} → {newVal}）';
        default:
          break;
      }
    }
    if (blockerIsPlayer && key === 'blockingTheWay') {
      return '你擋住了去路。';
    }
    if (key === 'attackHit') {
      if (attackerIsPlayer) return '你攻擊了 {defender}，造成 {damage} 點傷害。';
      if (defenderIsPlayer) return '{attacker} 攻擊了你，造成 {damage} 點傷害。';
    }
    if (key === 'attackCrit') {
      if (attackerIsPlayer) return '暴擊！你重創了 {defender}，造成 {damage} 點傷害！';
      if (defenderIsPlayer) return '暴擊！{attacker} 重創了你，造成 {damage} 點傷害！';
    }
    if (key === 'attackMissed') {
      if (attackerIsPlayer) return '你攻擊 {defender}，但被閃避了。';
      if (defenderIsPlayer) return '{attacker} 攻擊你，但被閃避了。';
    }
    if (key === 'actorDefeated' && defenderIsPlayer) {
      return '你被擊敗了！';
    }
    if (defenderIsPlayer) {
      switch (key) {
        case 'throwItemHitNoDamage':
          return '你朝自己投出了 {item}！';
        case 'throwItemHitDamage':
          return '你投出 {item} 擊中自己，造成 {damage} 點傷害！';
        case 'throwPotionRestore':
          return '你朝自己投擲 {item}，恢復了 {amount} 點{stat}！';
        case 'throwPotionIdentifyRestore':
          return '你朝自己投擲 {item}，恢復了 {amount} 點{stat}！你鑑定出了 {trueItem}！';
        case 'throwPotionParalyze':
          return '你朝自己投擲 {item}，全身麻痺了 {turns} 回合！';
        case 'throwPotionIdentifyParalyze':
          return '你朝自己投擲 {item}，全身麻痺了 {turns} 回合！你鑑定出了 {trueItem}！';
        case 'throwPotionSleep':
          return '你朝自己投擲 {item}，陷入了 {turns} 回合的沉睡！';
        case 'throwPotionIdentifySleep':
          return '你朝自己投擲 {item}，陷入了 {turns} 回合的沉睡！你鑑定出了 {trueItem}！';
        case 'throwPotionBlind':
          return '你朝自己投擲 {item}——黑暗籠罩了你的視線（持續 {turns} 回合）！';
        case 'throwPotionIdentifyBlind':
          return '你朝自己投擲 {item}——眼前陷入一片漆黑（持續 {turns} 回合）！你鑑定出了 {trueItem}！';
        case 'throwPotionSpeed':
          return '你朝自己投擲 {item}，行動速度翻倍了（持續 {turns} 回合）！';
        case 'throwPotionIdentifySpeed':
          return '你朝自己投擲 {item}，行動速度翻倍了（持續 {turns} 回合）！你鑑定出了 {trueItem}！';
        case 'throwPotionInvisible':
          return '你朝自己投擲 {item}，身影變得透明、進入隱形狀態（持續 {turns} 回合）！';
        case 'throwPotionIdentifyInvisible':
          return '你朝自己投擲 {item}，身影變得透明、進入隱形狀態（持續 {turns} 回合）！你鑑定出了 {trueItem}！';
        case 'throwPotionSeeInvisible':
          return '你朝自己投擲 {item}，雙眼湧現看破隱形的敏銳視力（持續 {turns} 回合）！';
        case 'throwPotionIdentifySeeInvisible':
          return '你朝自己投擲 {item}，雙眼湧現看破隱形的敏銳視力（持續 {turns} 回合）！你鑑定出了 {trueItem}！';
        case 'throwPotionGrowth':
          return '你朝自己投擲 {item}，你的 {attr} 提升了！（{oldVal} → {newVal}）';
        case 'throwPotionIdentifyGrowth':
          return '你朝自己投擲 {item}，你的 {attr} 提升了！（{oldVal} → {newVal}）你鑑定出了 {trueItem}！';
        case 'throwPotionCureBleeding':
          return '你朝自己投擲 {item}，傷口立刻止血了！';
        case 'throwPotionIdentifyCureBleeding':
          return '你朝自己投擲 {item}，傷口立刻止血了！你鑑定出了 {trueItem}！';
        case 'inflictedBleeding':
          return '你陷入了流血狀態（持續 {turns} 回合）！';
        case 'inflictedArmorBreak':
          return '你的防具被貫穿，陷入破甲狀態（持續 {turns} 回合）！';
        case 'inflictedFaint':
          return '你被猛擊震得昏厥了 {turns} 回合！';
        case 'inflictedBlind':
          return '暗影黑霧奪走了你的視線，使你失明 {turns} 回合！';
        case 'enemyMagicSkillHit':
          return '{attacker}對你施放「{skill}」，造成 {damage} 點魔法傷害！';
        case 'chargeKnockback':
          return '你被猛烈撞退了一格！';
        case 'throwPotionNoEffect':
          return '你朝自己投擲 {item}，藥瓶碎裂但沒有發生明顯的變化。';
        default:
          break;
      }
    }
  }

  return defaultTemplate;
}

export function localizeItemDisplayName(
  lang: LanguageCode,
  rawName: string,
  freshness?: 'fresh' | 'rotten'
): string {
  const catalog = TRANSLATIONS[lang];
  let baseRaw = rawName.trim();
  let detectedFreshness: 'fresh' | 'rotten' | undefined = freshness;

  const freshnessSuffixMatch = /^(.*?)\s*\((Fresh|Rotten)\)$/i.exec(baseRaw);
  if (freshnessSuffixMatch) {
    baseRaw = freshnessSuffixMatch[1].trim();
    if (!detectedFreshness) {
      detectedFreshness =
        freshnessSuffixMatch[2].toLowerCase() === 'rotten' ? 'rotten' : 'fresh';
    }
  }

  let enchantSuffix = '';
  const enchantSuffixMatch = /^(.*?)\s+\+(\d+)$/.exec(baseRaw);
  if (enchantSuffixMatch) {
    baseRaw = enchantSuffixMatch[1].trim();
    enchantSuffix = ` +${enchantSuffixMatch[2]}`;
  }

  let localizedBase = catalog.itemNames[baseRaw];
  if (!localizedBase) {
    const meatMatch = /^Meat of\s+(.+)$/i.exec(baseRaw);
    const potionColorMatch = /^(.+)\s+Potion$/i.exec(baseRaw);
    const scrollRuneMatch = /^Scroll\s+"(.+)"$/i.exec(baseRaw);
    if (meatMatch) {
      const enemyRaw = meatMatch[1].trim();
      const localizedEnemy = catalog.enemyNames[enemyRaw] ?? enemyRaw;
      localizedBase = lang === 'zh-TW' ? `${localizedEnemy}肉` : `Meat of ${localizedEnemy}`;
    } else if (potionColorMatch) {
      const colorEntry = findPotionColorByEnName(potionColorMatch[1]);
      if (colorEntry) {
        localizedBase =
          lang === 'zh-TW'
            ? `${colorEntry.zhColorName}藥水`
            : `${colorEntry.enColorName} Potion`;
      } else {
        localizedBase = baseRaw;
      }
    } else if (scrollRuneMatch) {
      localizedBase =
        lang === 'zh-TW'
          ? `卷軸「${scrollRuneMatch[1]}」`
          : `Scroll "${scrollRuneMatch[1]}"`;
    } else {
      localizedBase = baseRaw;
    }
  }

  const localizedWithEnchant = `${localizedBase}${enchantSuffix}`;
  if (!detectedFreshness) {
    return localizedWithEnchant;
  }
  const tag =
    detectedFreshness === 'rotten'
      ? catalog.itemModalsUI.rottenTag
      : catalog.itemModalsUI.freshTag;
  return lang === 'zh-TW' ? `${localizedWithEnchant}（${tag}）` : `${localizedWithEnchant} (${tag})`;
}

/**
 * Formats a localized log message given a language code, message key, and optional template parameters.
 */
export function formatLogMessage(
  lang: LanguageCode,
  key: LogMessageKey,
  params?: Readonly<Record<string, string | number>>
): string {
  const catalog = TRANSLATIONS[lang];
  let template = resolvePlayerAwareTemplate(lang, key, catalog.logTemplates[key], params);
  if (!params) {
    return template;
  }

  if (key === 'absorbedEnemySoul' && params.enemy === BLIND_UNSEEN_ACTOR_TOKEN) {
    template =
      lang === 'zh-TW'
        ? '你吸收了靈魂：【{soul}】！（{effect}）'
        : 'You absorbed a soul: {soul}! ({effect})';
  }

  if (typeof params.soulId === 'string') {
    const soulDef = getSoulById(params.soulId);
    if (soulDef) {
      template = template
        .replace(/\{soul\}/g, getLocalizedSoulName(soulDef, lang))
        .replace(/\{effect\}/g, getLocalizedSoulEffectSummary(soulDef, lang));
    }
  }

  if (typeof params.skillId === 'string') {
    const warSkillDef = getWarSkillById(params.skillId);
    if (warSkillDef) {
      template = template.replace(/\{skill\}/g, getLocalizedWarSkillName(warSkillDef, lang));
    } else {
      const magicSkillDef = getMagicSkillById(params.skillId);
      if (magicSkillDef) {
        template = template.replace(/\{skill\}/g, getLocalizedMagicSkillName(magicSkillDef, lang));
      }
    }
  }

  if (typeof params.trapId === 'string') {
    const trapDef = getTrapDefinitionById(params.trapId);
    if (trapDef) {
      template = template.replace(
        /\{trap\}/g,
        lang === 'zh-TW' ? trapDef.nameZh : trapDef.nameEn
      );
    }
  }

  for (const [paramKey, rawVal] of Object.entries(params)) {
    let displayVal = String(rawVal);
    if (displayVal === PLAYER_ACTOR_TOKEN) {
      displayVal =
        lang === 'zh-TW'
          ? '你'
          : paramKey === 'defender'
            ? 'you'
            : 'You';
    } else if (displayVal === BLIND_UNSEEN_ACTOR_TOKEN) {
      if (lang === 'zh-TW') {
        displayVal = '某個東西';
      } else {
        const sentenceStart = new RegExp(`(?:^|[.!?]\\s+)\\{${paramKey}\\}`).test(template);
        displayVal = sentenceStart ? 'Something' : 'something';
      }
    } else if (paramKey === 'generator' && catalog.mapGenerators[displayVal]) {
      displayVal = catalog.mapGenerators[displayVal];
    } else if (
      paramKey === 'slot' &&
      catalog.equipmentSlots[displayVal as EquipmentSlotId]
    ) {
      displayVal = catalog.equipmentSlots[displayVal as EquipmentSlotId];
    } else if (
      paramKey === 'attr' &&
      catalog.stats[displayVal as keyof typeof catalog.stats]
    ) {
      displayVal = catalog.stats[displayVal as keyof typeof catalog.stats];
    } else if (paramKey === 'stat') {
      const statLower = displayVal.toLowerCase();
      if (lang === 'zh-TW') {
        if (statLower === 'hp') displayVal = '生命值（HP）';
        else if (statLower === 'mp') displayVal = '魔力值（MP）';
        else if (statLower === 'sp') displayVal = '體力值（SP）';
      } else {
        displayVal = displayVal.toUpperCase();
      }
    } else if (
      (paramKey === 'actor' ||
        paramKey === 'attacker' ||
        paramKey === 'defender' ||
        paramKey === 'blocker' ||
        paramKey === 'enemy') &&
      catalog.enemyNames[displayVal]
    ) {
      displayVal = catalog.enemyNames[displayVal];
    } else if (
      paramKey === 'items' ||
      paramKey === 'item' ||
      paramKey === 'trueItem' ||
      paramKey === 'oldItem' ||
      paramKey === 'newItem' ||
      paramKey === 'targetItem'
    ) {
      displayVal = displayVal
        .split(', ')
        .map((entry) => {
          const trimmed = entry.trim();
          const match = /^(.*?)\s+x(\d+)$/.exec(trimmed);
          if (match) {
            const baseName = match[1];
            const count = match[2];
            return `${localizeItemDisplayName(lang, baseName)} x${count}`;
          }
          return localizeItemDisplayName(lang, trimmed);
        })
        .join(lang === 'zh-TW' ? '、' : ', ');
    }
    template = template.replace(new RegExp(`\\{${paramKey}\\}`, 'g'), displayVal);
  }
  return template;
}
